 	page_code = GET_INQ_PAGE_CODE(cmd);
 	alloc_len = GET_INQ_ALLOC_LENGTH(cmd);

-	inq_response = kmalloc(alloc_len, GFP_KERNEL);
+	/*
+	 * The ALLOCATION LENGTH field is user controlled (it comes from the
+	 * SCSI CDB supplied via SG_IO) and may be 0 or arbitrarily small.
+	 * The page handlers below always write a fixed amount of data into
+	 * inq_response - up to the 76 byte Device Identification VPD page -
+	 * regardless of alloc_len, so always allocate a buffer big enough
+	 * for the largest page that can be generated; otherwise a short
+	 * allocation length overflows the heap buffer (and kmalloc(0) even
+	 * returns ZERO_SIZE_PTR instead of NULL, which passes the NULL
+	 * check below).  Clamping alloc_len also prevents handlers such as
+	 * nvme_trans_device_id_page() from copying uninitialized slab data
+	 * back to userspace.
+	 */
+	if (alloc_len > 76)
+		alloc_len = 76;
+
+	inq_response = kmalloc(76, GFP_KERNEL);
 	if (inq_response == NULL) {
 		res = -ENOMEM;
 		goto out_mem;
 	}

